CREATE TABLE IF NOT EXISTS advisory_provenance (id BIGSERIAL PRIMARY KEY);
ALTER TABLE advisory_provenance ADD COLUMN IF NOT EXISTS advisory_id TEXT;
ALTER TABLE advisory_provenance ADD COLUMN IF NOT EXISTS auction_id TEXT;
ALTER TABLE advisory_provenance ADD COLUMN IF NOT EXISTS source_network TEXT;
ALTER TABLE advisory_provenance ADD COLUMN IF NOT EXISTS block_number BIGINT;
ALTER TABLE advisory_provenance ADD COLUMN IF NOT EXISTS block_hash TEXT;
ALTER TABLE advisory_provenance ADD COLUMN IF NOT EXISTS gas_units BIGINT;
ALTER TABLE advisory_provenance ADD COLUMN IF NOT EXISTS gas_price TEXT;
ALTER TABLE advisory_provenance ADD COLUMN IF NOT EXISTS gross_output TEXT;
ALTER TABLE advisory_provenance ADD COLUMN IF NOT EXISTS gas_cost TEXT;
ALTER TABLE advisory_provenance ADD COLUMN IF NOT EXISTS net_surplus TEXT;
ALTER TABLE advisory_provenance ADD COLUMN IF NOT EXISTS rejection_reason TEXT;
ALTER TABLE advisory_provenance ADD COLUMN IF NOT EXISTS route JSONB;
ALTER TABLE advisory_provenance ADD COLUMN IF NOT EXISTS assumptions JSONB;
ALTER TABLE advisory_provenance ADD COLUMN IF NOT EXISTS rejection_metadata JSONB;
ALTER TABLE advisory_provenance ADD COLUMN IF NOT EXISTS model_policy_metadata JSONB;
ALTER TABLE advisory_provenance ADD COLUMN IF NOT EXISTS payload JSONB;
ALTER TABLE advisory_provenance ADD COLUMN IF NOT EXISTS created_at TIMESTAMPTZ DEFAULT now();
UPDATE advisory_provenance SET advisory_id=COALESCE(advisory_id, 'legacy-'||id), auction_id=COALESCE(auction_id, 'legacy-'||id), source_network=COALESCE(source_network,'unknown'), block_number=COALESCE(block_number,0), block_hash=COALESCE(block_hash,'unknown'), gas_units=COALESCE(gas_units,0), gas_price=COALESCE(gas_price,'0'), gross_output=COALESCE(gross_output,'0'), gas_cost=COALESCE(gas_cost,'0'), net_surplus=COALESCE(net_surplus,'0'), route=COALESCE(route,'[]'::jsonb), assumptions=COALESCE(assumptions,'[]'::jsonb), rejection_metadata=COALESCE(rejection_metadata,'{}'::jsonb), model_policy_metadata=COALESCE(model_policy_metadata,'{}'::jsonb), payload=COALESCE(payload,'{}'::jsonb), created_at=COALESCE(created_at,now());
ALTER TABLE advisory_provenance ALTER COLUMN advisory_id SET NOT NULL, ALTER COLUMN auction_id SET NOT NULL, ALTER COLUMN source_network SET NOT NULL, ALTER COLUMN block_number SET NOT NULL, ALTER COLUMN block_hash SET NOT NULL, ALTER COLUMN gas_units SET NOT NULL, ALTER COLUMN gas_price SET NOT NULL, ALTER COLUMN gross_output SET NOT NULL, ALTER COLUMN gas_cost SET NOT NULL, ALTER COLUMN net_surplus SET NOT NULL, ALTER COLUMN route SET NOT NULL, ALTER COLUMN assumptions SET NOT NULL, ALTER COLUMN rejection_metadata SET NOT NULL, ALTER COLUMN model_policy_metadata SET NOT NULL, ALTER COLUMN payload SET NOT NULL, ALTER COLUMN created_at SET NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS advisory_provenance_advisory_id_key ON advisory_provenance(advisory_id);
